INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('0ebd9e63-2901-44d5-92d1-2bc8f33edbe0','studio_world_locations','9e789fe1-a93c-46f5-994c-32d984c7cb28','Sunken Dominion','f887a689-ad83-436b-9425-1d19fa24086f','renitaparker@me.com','{"id":"9e789fe1-a93c-46f5-994c-32d984c7cb28","name":"Sunken Dominion","tags":["imported-draft"],"map_x":50,"map_y":50,"user_id":"db618e68-0656-4b9b-b308-81e071faf745","image_url":null,"is_public":false,"created_at":"2026-09-25T05:04:21.574766+00:00","updated_at":"2026-09-25T05:04:21.574766+00:00","archived_at":null,"description":"Imported from a character profile. Review and classify this draft location.","canon_status":"concept","location_type":"other","spoiler_level":"private","codex_record_id":null,"workflow_status":"draft","parent_location_id":null}','2026-09-25T06:15:37.27483+00:00');
